#include <iostream>
using namespace std;
int a[1010][1010];
int main(){
    int M, N, H;
    cin >> M >> N >> H;
    for (int i = 1; i <= M; ++i) {
        for (int j = 1; j <= N; ++j) {
            cin >> a[i][j];
        }
    }
    int max_sum = 0;
    for (int i = 1; i <= M - 2; ++i) {
        for (int j = 1; j <= N - 2; ++j) {
            int local_max = a[i][j], local_min = a[i][j], local_sum = 0;
            for (int x = 0; x < 3; ++x) {
                for (int y = 0; y < 3; ++y) {
                    int height = a[i + x][j + y];
                    local_sum += height;
                    if (height > local_max) local_max = height;
                    if (height < local_min) local_min = height;
                }
            }
            if (local_max - local_min <= H) {
                if (local_sum > max_sum) {
                    max_sum = local_sum;
                }
            }
        }
    }
    cout << max_sum;
    return 0;
}

#include <iostream>
#include <algorithm>
#include <string>
#include <map>
#include <assert.h>
using namespace std;
struct Item {
    string name;
    int price;
    int priority;
};
bool cmp(const Item &a, const Item &b) {
    if (a.priority != b.priority) return a.priority < b.priority;
    if(a.price != b.price) return a.price < b.price;
    return a.name < b.name;
}
string s[1005];
std::map<string, int> mp;
int main(){
    int M, N;
    cin >> M >> N;
    Item items[N];
    for (int i = 0; i < N; ++i) {
        cin >> items[i].name >> items[i].price >> items[i].priority;
        assert(mp.find(items[i].name) == mp.end());
        mp[items[i].name] = items[i].priority;
    }
    sort(items, items + N, cmp);
    int budget = M;
    int count = 0;
    for (int i = 0; i < N; ++i) {
        if (items[i].price <= budget) {
            budget -= items[i].price;
            s[count++] = items[i].name;
        }
    }
    sort(s, s + count);
    for (int i = 0; i < count; ++i) {
        cout << s[i] << endl;
    }
    return 0;
}
